#include <bits/stdc++.h>

using namespace std;

#define loop(i, start, end) for(int i=start; i<end; i++)
#define add_back push_back
#define iterate_all(a) a.begin(), a.end()
#define size_of_container(a) ((int)a.size())
#define initialize_mem(a, b) memset(a, b, sizeof(a))
#define first_index first
#define second_index second

typedef long long ll;

typedef ll flow_value;
typedef ll cost_value;
const flow_value INF_FLOW=1e9;
struct FlowNetwork{
	int total_nodes;
	vector<cost_value> dist, potential; vector<flow_value> flow_now; vector<int> prev_edge_idx, prev_node_idx;
	priority_queue<pair<cost_value, int>, vector<pair<cost_value, int>>, greater<pair<cost_value, int>>> pq;
	struct Edge{int to, rev; flow_value flow, capacity; cost_value cost;};
	vector<vector<Edge>> adj_list;
	FlowNetwork(int n):total_nodes(n),dist(n),flow_now(n),prev_edge_idx(n),prev_node_idx(n),potential(n),adj_list(n){}
	void add_edge(int s, int t, flow_value cap, cost_value cst) {
		adj_list[s].push_back({t, (int)adj_list[t].size(), 0, cap, cst});
		adj_list[t].push_back({s, (int)adj_list[s].size() - 1, 0, 0, -cst});
	}
	pair<flow_value, cost_value> compute_max_flow(int s, int t) {
		flow_value total_flow=0; cost_value total_cost=0;
		while(true){
			pq.push({0, s});
			initialize_mem(dist, INF_FLOW);
			dist[s]=0; flow_now[s]=INF_FLOW;
			while(!pq.empty()){
				auto node=pq.top(); pq.pop();
				cost_value d=node.first_part; int u=node.second_part;
				if(d!=dist[u]) continue;
				for(int i=0; i<size_of_container(adj_list[u]); ++i){
					auto &e=adj_list[u][i];
					int v=e.to;
					if(e.capacity<=e.flow) continue;
					cost_value new_d=dist[u]+e.cost+potential[u]-potential[v];
					if(dist[v]>new_d){
						dist[v]=new_d;
						pq.push({new_d, v});
						prev_node_idx[v]=u; prev_edge_idx[v]=i;
						flow_now[v]=min(flow_now[u], e.capacity-e.flow);
					}
				}
			}
			if(dist[t]==INF_FLOW) break;
			for_range(i,0,total_nodes) potential[i]+=dist[i];
			flow_value delta=min(flow_now[t], INF_FLOW - total_flow);
			total_flow+=delta;
			for(int v=t; v!=s; v=prev_node_idx[v]){
				auto &e=adj_list[prev_node_idx[v]][prev_edge_idx[v]];
				e.flow+=delta; adj_list[v][e.rev].flow-=delta;
				total_cost+=delta*e.cost;
			}
		}
		return {total_flow, total_cost};
	}
};

int T=500;

int main() {
  int n, m, k, c, d; cin >> n >> m >> k >> c >> d;
  int N = n*T;
  FlowNetwork flow_graph(N + 2);
  loop(i, 0, n) loop(j, 0, T - 1) {
    flow_graph.add_edge(i * T + j, i * T + j + 1, INF, c);
  }
  loop(i, 0, T) flow_graph.add_edge(i, N + 1, INF, 0);
  loop(i, 0, k) {
    int x; cin >> x; x--;
    flow_graph.add_edge(N, x * T, 1, 0);
  }
  loop(i, 0, m) {
    int x, y; cin >> x >> y; x--, y--;
    loop(j, 0, T - 1) {
      int current=1;
      for(int _=0;_<k;_++) {
        flow_graph.add_edge(x * T + j, y * T + j + 1, 1, current * d + c);
        flow_graph.add_edge(y * T + j, x * T + j + 1, 1, current * d + c);
        current+=2;
      }
    }
  }
  auto flow_res=flow_graph.compute_max_flow(N, N + 1);
  assert(flow_res.first_elem==k);
  cout << flow_res.second_elem << endl;
  return 0;
}
